fn wide(s:&str)->Vec<u16>{OsStr::new(s).encode_wide().chain(Some(0)).collect()}
unsafe fn child(parent:HWND,class:&str,text:&str,style:u32,id:usize)->HWND{let c=wide(class);let t=wide(text);CreateWindowExW(0,c.as_ptr(),t.as_ptr(),WS_CHILD|WS_VISIBLE|style,0,0,10,10,parent,id as _,GetModuleHandleW(std::ptr::null()),null_mut())}
unsafe fn combo(hwnd:HWND,values:&[&str]){for v in values{let w=wide(v);SendMessageW(hwnd,CB_ADDSTRING,0,w.as_ptr() as LPARAM);}SendMessageW(hwnd,0x014E,0,0);}

