unsafe extern "system" fn proc(hwnd:HWND,msg:u32,w:WPARAM,l:LPARAM)->LRESULT{match msg{
 WM_CREATE=>{
  NAV=child(hwnd,"STATIC","YOUTUBE DESKTOP",0,0);TRENDING=child(hwnd,"BUTTON","Trending",0, TRENDING_ID);SUBS=child(hwnd,"BUTTON","Subscriptions",0,SUBS_ID);WATCH=child(hwnd,"BUTTON","Watch history",0,WATCH_ID);LIBRARY=child(hwnd,"BUTTON","Downloads",0,LIBRARY_ID);
  HISTORY=child(hwnd,"LISTBOX","",0x0001|0x00200000|0x00800000,HISTORY_ID);SEARCH_EDIT=child(hwnd,"EDIT","",0x0080|0x1000,0);SEARCH_BUTTON=child(hwnd,"BUTTON","Search",0x0001,SEARCH_ID);
  let cs=0x0003|0x00200000|0x00010000;TYPE=child(hwnd,"COMBOBOX","",cs,TYPE_ID);DATE=child(hwnd,"COMBOBOX","",cs,DATE_ID);DURATION=child(hwnd,"COMBOBOX","",cs,DURATION_ID);SORT=child(hwnd,"COMBOBOX","",cs,SORT_ID);
  combo(TYPE,&["All types","Videos","Playlists","Channels"]);combo(DATE,&["Any date","Last hour","Today","This week","This month","This year"]);combo(DURATION,&["Any length","Under 4 minutes","4–20 minutes","Over 20 minutes"]);combo(SORT,&["Relevance","Upload date","View count","Rating"]);
  RESULTS=child(hwnd,"LISTBOX","",0x0001|0x00200000|0x00800000|0x00100000,RESULTS_ID);THUMB=child(hwnd,"STATIC","",0x000E,0);DETAILS=child(hwnd,"EDIT","Select a result. Use MPV to play or yt-dlp to download.\r\n\r\nSearch results support videos, channels and playlists.",0x0004|0x0800|0x1000,0);
  PLAY=child(hwnd,"BUTTON","Play with MPV",0,PLAY_ID);DOWNLOAD=child(hwnd,"BUTTON","Download",0,DOWNLOAD_ID);OPEN=child(hwnd,"BUTTON","Open URL",0,OPEN_ID);SUBSCRIBE=child(hwnd,"BUTTON","Subscribe",0,SUBSCRIBE_ID);UNSUBSCRIBE=child(hwnd,"BUTTON","Unsubscribe",0,UNSUBSCRIBE_ID);STATUS=child(hwnd,"STATIC","Ready · YouTube data provided by RustyPipe",0,0);
  SEARCHES=service::load_search_history();fill_history();layout(hwnd);0
 }
 WM_SIZE=>{layout(hwnd);0}
 WM_KEYDOWN if w==13=>{start_search(hwnd);0}
 WM_COMMAND if (w&0xffff) as usize==SEARCH_ID=>{start_search(hwnd);0}
 WM_COMMAND if (w&0xffff) as usize==HISTORY_ID&&((w>>16)&0xffff) as usize==LB_DBLCLK=>{let i=SendMessageW(HISTORY,LB_GETCURSEL as u32,0,0);if i>=0{if let Some(q)=SEARCHES.get(i as usize){SetWindowTextW(SEARCH_EDIT,wide(q).as_ptr());start_search(hwnd);}}0}
 WM_COMMAND if (w&0xffff) as usize==RESULTS_ID&&((w>>16)&0xffff) as usize==LB_DBLCLK=>{if let Some(item)=selected(){open_url(hwnd,&item.url);if item.kind=="VIDEO"{let _=service::add_watch_history(&item);}}0}
 WM_COMMAND if (w&0xffff) as usize==RESULTS_ID=>{if let Some(item)=selected(){show_item(hwnd,item);}0}
 WM_COMMAND if (w&0xffff) as usize==TRENDING_ID=>{load_simple(hwnd,0);0}
 WM_COMMAND if (w&0xffff) as usize==SUBS_ID=>{show_items(hwnd,service::subscription_items(),"Saved subscriptions loaded.");0}
 WM_COMMAND if (w&0xffff) as usize==WATCH_ID=>{show_items(hwnd,service::watch_history(),"Watch history loaded.");0}
 WM_COMMAND if (w&0xffff) as usize==LIBRARY_ID=>{show_items(hwnd,service::offline_library(),"Local download library loaded.");0}
 WM_COMMAND if (w&0xffff) as usize==PLAY_ID=>{if let Some(i)=selected_item(){match service::launch_mpv(&i){Ok(())=>{let _=service::add_watch_history(&i);set_status("Launched MPV.");},Err(e)=>set_status(&e)}}0}
 WM_COMMAND if (w&0xffff) as usize==DOWNLOAD_ID=>{if let Some(i)=selected_item(){if i.kind=="LOCAL FILE"{set_status("This item is already in the local library.");}else{match service::launch_ytdlp(&i){Ok(())=>set_status("yt-dlp started. Files are saved in the application Downloads folder."),Err(e)=>set_status(&e)}}}0}
 WM_COMMAND if (w&0xffff) as usize==OPEN_ID=>{if let Some(i)=selected_item(){open_url(hwnd,&i.url);}0}
 WM_COMMAND if (w&0xffff) as usize==SUBSCRIBE_ID=>{if let Some(i)=selected_item(){if i.kind=="CHANNEL"{let id=i.id.clone();let h=hwnd as isize;thread::spawn(move||{let result=runtime().and_then(|rt|rt.block_on(service::subscribe(id)));unsafe{post_status(h as HWND,result.map(|_|"Channel subscribed.".into()).map_err(|e|e));}});}else{set_status("Select a channel result first.");}}0}
 WM_COMMAND if (w&0xffff) as usize==UNSUBSCRIBE_ID=>{if let Some(i)=selected_item(){match service::unsubscribe(&i.id){Ok(())=>{set_status("Unsubscribed.");show_items(hwnd,service::subscription_items(),"Subscriptions updated.");},Err(e)=>set_status(&e)}}0}
 SEARCH_DONE=>{let b=Box::from_raw(l as *mut (u64,Result<Vec<SearchResultItem>,String>));let(g,r)=*b;if g!=GENERATION{return 0}match r{Ok(v)=>show_items(hwnd,v,"Search complete."),Err(e)=>set_status(&format!("Search failed: {}",e))}0}
 DETAIL_DONE=>{let b=Box::from_raw(l as *mut (u64,Result<DetailData,String>));let(g,result)=*b;if g!=DETAIL_GENERATION{return 0}match result{Ok(d)=>{let text=format!("{}\r\n{}\r\n\r\n{}\r\n\r\nID: {}\r\n{}",d.heading,d.subheading,d.description,d.id,d.url);SetWindowTextW(DETAILS,wide(&text).as_ptr());if !d.items.is_empty(){let parent=SELECTED.clone();populate_items(d.items,"Channel/playlist contents loaded.");SELECTED=parent;}},Err(e)=>set_status(&format!("Details unavailable: {}",e))}0}
 (m) if m==WM_APP+4=>{let p=Box::from_raw(l as *mut String);set_status(p.as_str());0}
 THUMB_DONE=>{let b=Box::from_raw(l as *mut (u64,PathBuf));let(g,path)=*b;if g==THUMB_GENERATION{load_bitmap(path);}0}
 WM_DESTROY=>{if !CURRENT_BITMAP.is_null(){DeleteObject(CURRENT_BITMAP);CURRENT_BITMAP=null_mut();}if GDI_TOKEN!=0{GdiplusShutdown(GDI_TOKEN);GDI_TOKEN=0;}windows_sys::Win32::UI::WindowsAndMessaging::PostQuitMessage(0);0}
 _=>DefWindowProcW(hwnd,msg,w,l)
}}
fn runtime()->Result<tokio::runtime::Runtime,String>{tokio::runtime::Builder::new_multi_thread().enable_all().build().map_err(|e|e.to_string())}
unsafe fn selected()->Option<SearchResultItem>{let i=SendMessageW(RESULTS,LB_GETCURSEL as u32,0,0);if i<0{None}else{ITEMS.get(i as usize).cloned()}}
unsafe fn selected_item()->Option<SearchResultItem>{SELECTED.clone().or_else(||selected())}
unsafe fn set_status(s:&str){SetWindowTextW(STATUS,wide(s).as_ptr());}
unsafe fn populate_items(items:Vec<SearchResultItem>,message:&str){DETAIL_GENERATION=DETAIL_GENERATION.wrapping_add(1);THUMB_GENERATION=THUMB_GENERATION.wrapping_add(1);ITEMS=items;SendMessageW(RESULTS,LB_RESET as u32,0,0);for i in ITEMS.iter(){let line=format!("[{}] {}  —  {}",i.kind,i.title,i.subtitle);SendMessageW(RESULTS,LB_ADD as u32,0,wide(&line).as_ptr() as LPARAM);}SELECTED=None;set_status(&format!("{} {} item(s).",message,ITEMS.len()));}
unsafe fn show_items(_hwnd:HWND,items:Vec<SearchResultItem>,message:&str){populate_items(items,message);SetWindowTextW(DETAILS,wide("Select an item to inspect it.\r\n\r\nDouble-click videos to open in the browser; use Play with MPV for external playback.").as_ptr());}
unsafe fn show_item(hwnd:HWND,item:SearchResultItem){DETAIL_GENERATION=DETAIL_GENERATION.wrapping_add(1);THUMB_GENERATION=THUMB_GENERATION.wrapping_add(1);let detail_generation=DETAIL_GENERATION;let thumb_generation=THUMB_GENERATION;SELECTED=Some(item.clone());let summary=format!("{}\r\n{}\r\n\r\nType: {}\r\nID: {}\r\nURL: {}\r\n\r\nLoading full details…",item.title,item.subtitle,item.kind,item.id,item.url);SetWindowTextW(DETAILS,wide(&summary).as_ptr());if !item.thumbnail_url.is_empty(){let url=item.thumbnail_url.clone();let id=item.id.clone();let h=hwnd as isize;thread::spawn(move||{let path=cache_thumbnail_path(&id);let result=download_thumbnail(&url,&path);if result{let boxed=Box::into_raw(Box::new((thumb_generation,path)));if unsafe{PostMessageW(h as HWND,THUMB_DONE,0,boxed as LPARAM)}==0{unsafe{drop(Box::from_raw(boxed));}}}});}
 if item.kind=="VIDEO"||item.kind=="CHANNEL"||item.kind=="PLAYLIST"{let id=item.id.clone();let kind=item.kind.clone();let h=hwnd as isize;thread::spawn(move||{let result=runtime().and_then(|rt|rt.block_on(async move{match kind.as_str(){"VIDEO"=>service::video_detail(id).await,"CHANNEL"=>service::channel_detail(id).await,_=>service::playlist_detail(id).await}}));let boxed=Box::into_raw(Box::new((detail_generation,result)));if unsafe{PostMessageW(h as HWND,DETAIL_DONE,0,boxed as LPARAM)}==0{unsafe{drop(Box::from_raw(boxed));}}});}}
unsafe fn start_search(hwnd:HWND){DETAIL_GENERATION=DETAIL_GENERATION.wrapping_add(1);THUMB_GENERATION=THUMB_GENERATION.wrapping_add(1);let n=GetWindowTextLengthW(SEARCH_EDIT);if n<=0{set_status("Enter a search query first.");return}let mut b=vec![0u16;n as usize+1];GetWindowTextW(SEARCH_EDIT,b.as_mut_ptr(),b.len() as i32);let q=String::from_utf16_lossy(&b[..n as usize]).trim().to_owned();if q.is_empty(){return}GENERATION=GENERATION.wrapping_add(1);let g=GENERATION;let o=SearchOptions{item_type:combo_index(TYPE),date:combo_index(DATE),duration:combo_index(DURATION),sort:combo_index(SORT)};let _=service::save_search_history(&q);SEARCHES=service::load_search_history();fill_history();set_status("Searching YouTube…");let h=hwnd as isize;thread::spawn(move||{let r=runtime().and_then(|rt|rt.block_on(service::search(q,o)));let p=Box::into_raw(Box::new((g,r)));if unsafe{PostMessageW(h as HWND,SEARCH_DONE,0,p as LPARAM)}==0{unsafe{drop(Box::from_raw(p));}}});}
unsafe fn combo_index(h:HWND)->usize{let n=SendMessageW(h,CB_GETCURSEL,0,0);if n<0{0}else{n as usize}}
unsafe fn fill_history(){SendMessageW(HISTORY,LB_RESET as u32,0,0);for q in SEARCHES.iter(){SendMessageW(HISTORY,LB_ADD as u32,0,wide(q).as_ptr() as LPARAM);}}
unsafe fn load_simple(hwnd:HWND,_kind:u8){GENERATION=GENERATION.wrapping_add(1);let g=GENERATION;set_status("Loading trending videos…");let h=hwnd as isize;thread::spawn(move||{let r=runtime().and_then(|rt|rt.block_on(service::trending()));let p=Box::into_raw(Box::new((g,r)));if unsafe{PostMessageW(h as HWND,SEARCH_DONE,0,p as LPARAM)}==0{unsafe{drop(Box::from_raw(p));}}});}
unsafe fn open_url(hwnd:HWND,url:&str){let op=wide("open");let u=wide(url);let r=ShellExecuteW(hwnd,op.as_ptr(),u.as_ptr(),std::ptr::null(),std::ptr::null(),SW_SHOWNORMAL);if (r as isize)<=32{set_status("Could not open URL. Check default browser association.");}}
fn cache_thumbnail_path(id:&str)->PathBuf{let base=std::env::var_os("APPDATA").map(PathBuf::from).unwrap_or_else(||PathBuf::from("."));let dir=base.join("youtube-desktop").join("thumbnails");let _=std::fs::create_dir_all(&dir);let safe:String=id.chars().filter(|c|c.is_ascii_alphanumeric()||*c=='-'||*c=='_').collect();dir.join(format!("{}.jpg",safe))}
fn download_thumbnail(url:&str,path:&PathBuf)->bool{if path.exists(){return true}let u=wide(url);let p=wide(&path.to_string_lossy());unsafe{URLDownloadToFileW(null_mut(),u.as_ptr(),p.as_ptr(),0,null_mut())==0}}
unsafe fn load_bitmap(path:PathBuf){let p=wide(&path.to_string_lossy());let mut image=null_mut();if GdipCreateBitmapFromFile(p.as_ptr(),&mut image)==0&&!image.is_null(){let mut bitmap=null_mut();if GdipCreateHBITMAPFromBitmap(image,&mut bitmap,0)==0&&!bitmap.is_null(){if !CURRENT_BITMAP.is_null(){DeleteObject(CURRENT_BITMAP);}CURRENT_BITMAP=bitmap;SendMessageW(THUMB,STM_SETIMAGE,IMAGE_BITMAP,bitmap as LPARAM);}GdipDisposeImage(image);}}
unsafe fn post_status(hwnd:HWND,result:Result<String,String>){let s=result.unwrap_or_else(|e|e);let p=Box::into_raw(Box::new(s));if PostMessageW(hwnd,WM_APP+4,0,p as LPARAM)==0{drop(Box::from_raw(p));}}
unsafe fn layout(hwnd:HWND){let mut r:RECT=std::mem::zeroed();if GetClientRect(hwnd,&mut r)==0{return}let w=r.right-r.left;let h=r.bottom-r.top;let nav=170;let details=(w/3).max(280);let main=(w-nav-details-64).max(250);MoveWindow(NAV,0,0,nav,h,1);MoveWindow(TRENDING,12,42,nav-24,30,1);MoveWindow(SUBS,12,78,nav-24,30,1);MoveWindow(WATCH,12,114,nav-24,30,1);MoveWindow(LIBRARY,12,150,nav-24,30,1);MoveWindow(HISTORY,12,220,nav-24,(h-240).max(80),1);MoveWindow(SEARCH_EDIT,nav+18,14,main-90,32,1);MoveWindow(SEARCH_BUTTON,nav+main-64,14,82,32,1);let fw=(main+details-4)/4;MoveWindow(TYPE,nav+18,56,fw-5,220,1);MoveWindow(DATE,nav+18+fw,56,fw-5,220,1);MoveWindow(DURATION,nav+18+2*fw,56,fw-5,220,1);MoveWindow(SORT,nav+18+3*fw,56,fw-5,220,1);MoveWindow(RESULTS,nav+18,92,main,(h-145).max(100),1);let dx=nav+main+22;MoveWindow(THUMB,dx,92,details-36,160,1);MoveWindow(DETAILS,dx,260,details-36,(h-380).max(100),1);let by=h-104;MoveWindow(PLAY,dx,by,details/2-22,30,1);MoveWindow(DOWNLOAD,dx+details/2-16,by,details/2-22,30,1);MoveWindow(OPEN,dx,by+36,details/3-14,30,1);MoveWindow(SUBSCRIBE,dx+details/3-8,by+36,details/3-14,30,1);MoveWindow(UNSUBSCRIBE,dx+2*(details/3)-2,by+36,details/3-14,30,1);MoveWindow(STATUS,nav+18,h-34,w-nav-36,22,1);}
